def slot_runtime_summary() -> dict[str, Any]:
    slots = load_active_slots()

    readonly = [
        slot
        for slot in slots
        if slot["slot_class"] == "READ_ONLY"
    ]

    mutation = [
        slot
        for slot in slots
        if slot["slot_class"] == "MUTATION"
    ]

    return {
        "active_slots": len(slots),
        "readonly_slots_active": len(readonly),
        "readonly_slots_capacity": 1,
        "mutation_slots_active": len(mutation),
        "mutation_slots_capacity": 1,
        "slot_job_ids": [
            slot["job_id"]
            for slot in slots
        ],
        "slot_states": {
            slot["slot_id"]: slot["state"]
            for slot in slots
        },
    }


def observable_slot_runtime_summary() -> dict[str, Any]:
    """Return fail-closed slot observability without mutating runtime state."""
    try:
        summary = slot_runtime_summary()
    except SlotRuntimeError as exc:
        return {
            "slot_runtime_status": "BLOCKED",
            "slot_runtime_error": str(exc),
            "active_slots": None,
            "readonly_slots_active": None,
            "readonly_slots_capacity": 1,
            "mutation_slots_active": None,
            "mutation_slots_capacity": 1,
            "slot_job_ids": [],
            "slot_states": {},
        }

    return {
        "slot_runtime_status": "READY",
        **summary,
    }

